// @vitest-environment node
/**
 * Golden URLs: `__fixtures__/image-golden.jsonl` was generated by running each
 * v8 storefront's own image helpers (the vendored v7 `getOptimizedMediaUrl` /
 * `getSrcSet` copies, the next/image loaders, a fixed-frame catalog loader and
 * a mobile app's VTEX helpers) over one corpus of sources. Each config below
 * is the `createImageUrl` call that site makes in v8, and must reproduce its
 * URLs byte for byte. The one intended change: the next/image loader still on
 * VTEX's file-manager `?width=` resizer (500s for raster files since
 * 2026-10-07) moves to the Thumbor route, and a mobile app's hand copies that
 * disagree with its own site-loader copy follow that copy. Those cases carry
 * `before` (the old URL) and `reason`.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  createImageUrl,
  decoCdn,
  type ImageUrl,
  parseSrcSet,
  preloadLink,
  type ResizeOptions,
  shopify,
  srcSet,
  vtexCatalog,
  vtexFileManager,
} from "./image.ts";

interface Case {
  config: string;
  call: "url" | "srcSet" | "isOptimizable";
  src: string;
  opts?: ResizeOptions & { widths?: number[]; factors?: number[] };
  ratio?: [number, number];
  expected: string | boolean | null;
  before?: string;
  reason?: string;
}

const cases: Case[] = readFileSync(
  new URL("./__fixtures__/image-golden.jsonl", import.meta.url),
  "utf-8",
)
  .split("\n")
  .filter(Boolean)
  .map((line) => JSON.parse(line));

/** v7's TanStack helper: VTEX and Shopify natively, everything else through the Deco CDN. */
const tanstackV7 = (domain?: string, quality?: "high") =>
  createImageUrl({
    providers: [
      vtexCatalog({ size: "exact" }),
      shopify(),
      decoCdn({ domain, quality, proxyOtherHosts: true }),
    ],
  });

/** The next/image loaders: VTEX catalog as webp, file manager through Thumbor, Deco CDN at "high". */
const nextLoader = createImageUrl({
  providers: [
    vtexCatalog({ size: "auto", format: "webp", quality: 8, anyHost: true }),
    vtexFileManager({ via: "thumbor", quality: 8 }),
    decoCdn({ quality: "high", layout: "quality-last" }),
  ],
});

const CONFIGS: Record<string, (c: Case) => ImageUrl> = {
  "tanstack-decoims-high": () => tanstackV7("decoims.com", "high"),
  "tanstack-default": () => tanstackV7(),
  "tanstack-anchored": () => tanstackV7(),
  "next-thumbor": () => nextLoader,
  "next-query": () => nextLoader,
  "next-catalog-frame": (c) => {
    const [w, h] = c.ratio as [number, number];
    return createImageUrl({ providers: [vtexCatalog({ size: { ratio: h / w }, anyHost: true })] });
  },
  "next-catalog-exact": () =>
    createImageUrl({ providers: [vtexCatalog({ size: "exact", anyHost: true })] }),
  "app-vtex-exact": () =>
    createImageUrl({ providers: [vtexCatalog({ size: "exact", anyHost: true })] }),
  "app-vtex-auto": () =>
    createImageUrl({
      providers: [vtexCatalog({ size: "auto", format: "webp", quality: 10, anyHost: true })],
    }),
};

function run(c: Case): string | boolean | null {
  const url = CONFIGS[c.config](c);
  if (c.call === "isOptimizable") return url.isOptimizable(c.src);
  if (c.call === "srcSet") return srcSet(url, c.src, c.opts ?? {}) ?? null;
  return url(c.src, c.opts as ResizeOptions);
}

describe("golden URLs: each storefront's current helpers, byte for byte", () => {
  it("covers every config", () => {
    expect(new Set(cases.map((c) => c.config))).toEqual(new Set(Object.keys(CONFIGS)));
  });

  for (const config of Object.keys(CONFIGS)) {
    it(config, () => {
      const mine = cases.filter((c) => c.config === config);
      expect(mine.length).toBeGreaterThan(0);
      const diffs = mine
        .map((c) => ({ c, got: run(c) }))
        .filter(({ c, got }) => got !== c.expected)
        .map(({ c, got }) => ({
          call: c.call,
          src: c.src,
          opts: c.opts,
          expected: c.expected,
          got,
        }));
      expect(diffs).toEqual([]);
    });
  }

  it("the intended changes are the file-manager resizer and the mobile app's diverging hand copies", () => {
    const changed = cases.filter((c) => c.before !== undefined);
    expect(changed.length).toBeGreaterThan(0);
    for (const c of changed) {
      expect(c.reason).toBeTruthy();
      if (c.config === "next-query") {
        expect(c.src).toMatch(/vtexassets\.com\/assets\//);
        expect(c.before).toMatch(/[?&]width=\d+&aspect=true/);
      } else {
        expect(["app-vtex-exact", "app-vtex-auto"]).toContain(c.config);
      }
    }
  });
});

describe("decoCdn", () => {
  const url = createImageUrl({ providers: [decoCdn()] });
  const asset = "https://assets.decocache.com/a-storefront/abc/hero.jpg";

  it("defaults fit to contain without a height and cover with one", () => {
    expect(url(asset, { width: 640 })).toBe(
      "https://assets.decocms.com/image?fit=contain&width=640&src=a-storefront/abc/hero.jpg",
    );
    expect(url(asset, { width: 640, height: 320 })).toBe(
      "https://assets.decocms.com/image?fit=cover&width=640&height=320&src=a-storefront/abc/hero.jpg",
    );
  });

  it("re-formats an already-resized URL from its source instead of asking for src=image", () => {
    for (const layout of ["src-last", "quality-last"] as const) {
      const u = createImageUrl({ providers: [decoCdn({ layout, quality: "high" })] });
      const once = u(asset, { width: 828 });
      expect(u(once, { width: 828 })).toBe(once);
      expect(u(once, { width: 320 })).toBe(u(asset, { width: 320 }));
      expect(u.parse(once)).toEqual({
        provider: "deco",
        original: "https://assets.decocms.com/a-storefront/abc/hero.jpg",
        width: 828,
        height: undefined,
      });
    }
  });

  it("strips only leading asset hosts", () => {
    const nested = `https://images.example.com/p?u=${asset}`;
    expect(url.isOptimizable(nested)).toBe(false);
    expect(url(nested, { width: 10 })).toBe(nested);
  });

  it("keeps decoims.com URLs whole on an Azion CDN", () => {
    const azion = createImageUrl({
      providers: [decoCdn({ domain: "https://deco-assets.edgedeco.com/", proxyOtherHosts: true })],
    });
    expect(azion("https://decoims.com/a/b.png", { width: 10, fit: "cover" })).toBe(
      "https://deco-assets.edgedeco.com/image?fit=cover&width=10&src=https://decoims.com/a/b.png",
    );
  });

  it("ignores numeric qualities and takes a per-call tier", () => {
    const u = createImageUrl({ providers: [decoCdn({ quality: "medium" })] });
    expect(u(asset, { width: 10, quality: 90 })).toContain("quality=medium");
    expect(u(asset, { width: 10, quality: "low" })).toContain("quality=low");
  });
});

describe("VTEX providers", () => {
  const catalog = "https://store.vtexassets.com/arquivos/ids/123/shoe.jpg?v=1";

  it("catalog: exact, auto and ratio boxes are idempotent and parse back", () => {
    for (const size of ["exact", "auto", { ratio: 1.25 }] as const) {
      const u = createImageUrl({ providers: [vtexCatalog({ size })] });
      const once = u(catalog, { width: 400 });
      expect(u(once, { width: 400 })).toBe(once);
      expect(u.parse(once)?.original).toBe(catalog);
      expect(u.parse(once)?.width).toBe(400);
    }
  });

  it("catalog: only VTEX hosts unless anyHost", () => {
    const own = "https://www.example.com/arquivos/ids/1/a.jpg";
    expect(createImageUrl({ providers: [vtexCatalog({ size: "exact" })] }).isOptimizable(own)).toBe(
      false,
    );
    expect(
      createImageUrl({ providers: [vtexCatalog({ size: "exact", anyHost: true })] }).isOptimizable(
        own,
      ),
    ).toBe(true);
  });

  it("file manager: Thumbor URLs parse back to the asset and re-format the same", () => {
    const u = createImageUrl({ providers: [vtexFileManager({ via: "thumbor" })] });
    const asset = "https://store.vtexassets.com/assets/vtex.file-manager-graphql/images/a___b.png";
    const once = u(asset, { width: 640 });
    expect(once).toBe(
      `https://store.vtexassets.com/unsafe/640x0/filters:no_upscale():quality(80):format(webp)/${encodeURIComponent(asset)}`,
    );
    expect(u(once, { width: 640 })).toBe(once);
    expect(u.parse(once)).toEqual({ provider: "vtex-file-manager", original: asset, width: 640 });
  });

  it("shopify is idempotent and parses back", () => {
    const u = createImageUrl({ providers: [shopify()] });
    const src = "https://cdn.shopify.com/s/files/1/products/a.jpg?v=1";
    const once = u(src, { width: 300, height: 200 });
    expect(u(once, { width: 300, height: 200 })).toBe(once);
    expect(u.parse(once)).toEqual({ provider: "shopify", original: src, width: 300, height: 200 });
  });
});

describe("createImageUrl", () => {
  const url = createImageUrl({ providers: [vtexCatalog({ size: "exact" }), shopify(), decoCdn()] });

  it('returns "" for an empty src and passes data: URIs and unknown sources through', () => {
    expect(url("", { width: 1 })).toBe("");
    expect(url("data:image/png;base64,AA==", { width: 1 })).toBe("data:image/png;base64,AA==");
    expect(url("https://images.example.com/a.jpg", { width: 1 })).toBe(
      "https://images.example.com/a.jpg",
    );
    expect(url.isOptimizable("")).toBe(false);
    expect(url.isOptimizable("data:image/png;base64,AA==")).toBe(false);
  });

  it("lists the providers' hosts once", () => {
    expect(url.hosts()).toEqual([
      "*.vtexassets.com",
      "*.vteximg.com.br",
      "*.myvtex.com",
      "cdn.shopify.com",
      "assets.decocms.com",
    ]);
  });
});

describe("srcSet, parseSrcSet and preloadLink", () => {
  const url = createImageUrl({ providers: [vtexCatalog({ size: "exact" })] });
  const src = "https://store.vtexassets.com/arquivos/ids/1/a.jpg";

  it("builds candidates from widths with a fixed ratio", () => {
    expect(srcSet(url, src, { widths: [100, 200], ratio: 1.5 })).toBe(
      "https://store.vtexassets.com/arquivos/ids/1-100-150/a.jpg 100w, https://store.vtexassets.com/arquivos/ids/1-200-300/a.jpg 200w",
    );
    expect(srcSet(url, "", { width: 100 })).toBeUndefined();
    expect(srcSet(url, src, {})).toBeUndefined();
  });

  it("parses what srcSet builds, and URLs with commas", () => {
    const set = srcSet(url, src, { width: 100, height: 100 }) as string;
    expect(parseSrcSet(set)).toEqual([
      { url: "https://store.vtexassets.com/arquivos/ids/1-100-100/a.jpg", w: 100 },
      { url: "https://store.vtexassets.com/arquivos/ids/1-200-200/a.jpg", w: 200 },
    ]);
    expect(parseSrcSet("a.jpg 1x,b,c.jpg 2x, d.jpg")).toEqual([
      { url: "a.jpg", x: 1 },
      { url: "b,c.jpg", x: 2 },
      { url: "d.jpg" },
    ]);
  });

  it("preloadLink carries href, srcset, sizes, media and a high priority", () => {
    expect(
      preloadLink(url, src, {
        width: 100,
        height: 100,
        sizes: "100vw",
        media: "(max-width: 767px)",
      }),
    ).toEqual({
      rel: "preload",
      as: "image",
      href: "https://store.vtexassets.com/arquivos/ids/1-100-100/a.jpg",
      imageSrcSet:
        "https://store.vtexassets.com/arquivos/ids/1-100-100/a.jpg 100w, https://store.vtexassets.com/arquivos/ids/1-200-200/a.jpg 200w",
      imageSizes: "100vw",
      media: "(max-width: 767px)",
      fetchPriority: "high",
    });
  });
});

describe("the ./image subpath", () => {
  it("package.json maps it to the source and the build", () => {
    const pkg = JSON.parse(readFileSync(new URL("../../package.json", import.meta.url), "utf-8"));
    expect(pkg.exports["./image"]).toEqual({
      types: "./dist/v8/image.d.ts",
      source: "./src/v8/image.ts",
      default: "./dist/v8/image.js",
    });
  });

  it("exports exactly the documented runtime names", async () => {
    expect(Object.keys(await import("./image.ts")).sort()).toEqual([
      "createImageUrl",
      "decoCdn",
      "parseSrcSet",
      "preloadLink",
      "shopify",
      "srcSet",
      "vtexCatalog",
      "vtexFileManager",
    ]);
  });
});
